catalog_ui_policy.script_true:
function onCondition() {
    // Obtenha o valor da data selecionada pelo usuário.
    // Substitua 'nome_da_variavel_da_data' pelo nome real da variável de data no seu item de catálogo.
    var dataSelecionada = g_form.getValue('purchase_date');

    // Crie um objeto de data a partir da string de data do campo.
    var dataObjeto = new Date(dataSelecionada);

    // Obtenha a data e hora atuais.
    var hoje = new Date();

    // Zere as horas, minutos, segundos e milissegundos para comparar apenas as datas.
    dataObjeto.setHours(0, 0, 0, 0);
    hoje.setHours(0, 0, 0, 0);

    // Verifique se a data selecionada é posterior à data de hoje.
    if (dataObjeto > hoje) {
        // Exibe uma mensagem de erro para o usuário.
        g_form.showFieldMsg('purchase_date', 'Não é possível solicitar reembolsos para datas futuras.', 'error');

        // Limpa o valor do campo.
        g_form.setValue('purchase_date', '');

        // Retorna false para que o Catalog UI Policy não seja aplicado.
        return false;
    }
}
